ALTER TABLE public.preferencias_munim ADD COLUMN sugestoes_data date, ADD COLUMN sugestoes_usadas integer NOT NULL DEFAULT 0; CREATE OR REPLACE FUNCTION public.limitar_sugestoes_pessoais() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE dia date; usadas integer; limite integer; BEGIN IF NEW.origem<>'sugerida' THEN RETURN NEW; END IF; INSERT INTO public.preferencias_munim(user_id) VALUES(NEW.user_id) ON CONFLICT(user_id) DO NOTHING; SELECT (now() AT TIME ZONE coalesce(p.fuso,'America/Sao_Paulo'))::date INTO dia FROM public.profiles p WHERE p.id=NEW.user_id; SELECT CASE WHEN sugestoes_data=dia THEN sugestoes_usadas ELSE 0 END,sugestoes_dia INTO usadas,limite FROM public.preferencias_munim WHERE user_id=NEW.user_id FOR UPDATE; IF usadas>=least(limite,3) THEN RETURN NULL; END IF; IF EXISTS(SELECT 1 FROM public.ligacoes WHERE item_a=NEW.item_a AND item_b=NEW.item_b) THEN RETURN NULL; END IF; UPDATE public.preferencias_munim SET sugestoes_data=dia,sugestoes_usadas=usadas+1 WHERE user_id=NEW.user_id; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.limitar_sugestoes_pessoais() FROM PUBLIC,anon,authenticated; CREATE TRIGGER ligacoes_daily_limit BEFORE INSERT ON public.ligacoes FOR EACH ROW EXECUTE FUNCTION public.limitar_sugestoes_pessoais();